    if not m:
      continue
    fm=m.group(1)
    for f in ('plan_workstations','execution_workstations'):
      mm=re.search(rf'^{re.escape(f)}:[ \t]*(.*)$',fm,re.M)
      ok=False
      if mm:
        v=mm.group(1).strip()
        if v and v not in {'[]','null','~'}:
          ok=True
      if not ok:
        missing.append((str(p),f))
print('missing_count',len(missing))
print('\n'.join(f"{p}::{f}" for p,f in missing[:20]))
